def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(size, separators):
        bounds = [-1] + separators + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)
                if bounds[i + 1] > bounds[i] + 1]

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    separator_colors = {grid[r][0] for r in sep_rows}
    separator_colors.update(grid[0][c] for c in sep_cols)

    counts = {}
    for row in grid:
        for value in row:
            if value not in separator_colors:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    result = []
    for r0, r1 in row_spans:
        out_row = []
        for c0, c1 in col_spans:
            markers = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            out_row.append(1 if markers == 2 else background)
        result.append(out_row)
    return result
